mapper.update:
UPDATE task_submission
SET task_id  = #{taskId},
    user_id  = #{userId},
    content  = #{content},
    file_url = #{fileUrl}
WHERE id = #{id}

UPDATE task_submission
SET status = #{status}
WHERE id = #{id}

mapper.select:
SELECT id, task_id, user_id, content, file_url, submit_time, status
FROM task_submission
WHERE id = #{id}
